// ===== ADMIN LOGIN (same as Stage2) =====
class LoginPage extends StatefulWidget { @override _LoginPageState createState() => _LoginPageState(); }
class _LoginPageState extends State<LoginPage> {
  final userCtrl = TextEditingController(); final passCtrl = TextEditingController();
  int attempts=0, blockSeconds=0; List<String> logs=[]; Timer? timer;
  final String REAL_USER="Scansafeadmin"; final String REAL_PASS="SSA_86Primrose";
  void login(){ if(blockSeconds>0) return; if(userCtrl.text==REAL_USER && passCtrl.text==REAL_PASS){ Navigator.pushReplacement(context, MaterialPageRoute(builder: (_)=> DashboardPage())); return; } attempts++; setState(()=> logs.insert(0, "${DateTime.now().toString().substring(11,19)} - HONEYPOT ${userCtrl.text}")); if(attempts>=3){ setState(()=> blockSeconds=30); timer=Timer.periodic(Duration(seconds:1),(t){ setState((){ blockSeconds--; if(blockSeconds<=0){ t.cancel(); attempts=0; } }); }); } }
  @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: Text("ADMIN LOGIN")), body: SingleChildScrollView(padding: EdgeInsets.all(20), child: Column(children: [Icon(Icons.shield, size:80, color: Color(0xFF0D2C54)), TextField(controller: userCtrl, decoration: InputDecoration(labelText: "Username", border: OutlineInputBorder())), SizedBox(height:10), TextField(controller: passCtrl, obscureText:true, decoration: InputDecoration(labelText: "Password", border: OutlineInputBorder())), SizedBox(height:15), if(attempts>=3) Container(width: double.infinity, padding: EdgeInsets.all(12), color: Colors.red[100], child: Text("🚫 BLOCKED $blockSeconds sec", textAlign: TextAlign.center)), SizedBox(height:10), SizedBox(width: double.infinity, height:50, child: ElevatedButton(onPressed: blockSeconds>0?null:login, style: ElevatedButton.styleFrom(backgroundColor: Color(0xFF0D2C54)), child: Text(blockSeconds>0?"BLOCKED":"LOGIN ADMIN", style: TextStyle(color: Colors.white)))),]))); }
}

// ===== BRAND OWNER LOGIN =====
