// ===== CITIZEN PUBLIC PAGE - NO LOGIN =====
class CitizenPage extends StatefulWidget { @override _CitizenPageState createState() => _CitizenPageState(); }
class _CitizenPageState extends State<CitizenPage> {
  double? lat,lng; String gps="Getting location... Allow permission!";
  String selectedBrand="Coca-Cola 2L"; final barcodeCtrl=TextEditingController();
  final List<String> brands=["Coca-Cola 2L","Lays Tomato","Sunlight Dish 750ml","Castle Lager","White Star Maize","Ariel Washing","Colgate Toothpaste","Other - Type in barcode"];
  @override void initState(){ super.initState(); _getGPS(); }
  void _getGPS(){ try{ html.window.navigator.geolocation.getCurrentPosition().then((p){ setState(){ lat=p.coords!.latitude!.toDouble(); lng=p.coords!.longitude!.toDouble(); gps="${lat!.toStringAsFixed(6)}, ${lng!.toStringAsFixed(6)} - Thank you!"; }; }).catchError((e){ setState(()=> gps="Allow location! Using Bethelsdorp"); lat=-33.8529; lng=25.5800; }); }catch(e){ lat=-33.8529; lng=25.5800; } }
  void submit(){ double useLat=lat??-33.8529; double useLng=lng??25.5800; String saps="SAPS-${DateTime.now().millisecondsSinceEpoch}"; String msg="🚨 *ScanSafeAfrica CITIZEN REPORT*\n\nBrand: $selectedBrand\nBarcode: ${barcodeCtrl.text}\nStatus: SUSPECT - VERIFICATION REQUIRED\nLocation: $useLat,$useLng\nGoogle Maps: https://www.google.com/maps/search/?api=1&query=$useLat,$useLng\nSAPS Ref: $saps\nTime: ${DateTime.now()}\n\nReported via Citizen App - Bethelsdorp";
    String waUrl="https://wa.me/27700000000?text=${Uri.encodeComponent(msg)}";
    showDialog(context: context, builder: (_)=> AlertDialog(title: Text("✅ THANK YOU! REPORT SENT!"), content: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [Text("Your SUSPECT report has been logged for SAPS & CIPC:", style: TextStyle(fontWeight: FontWeight.bold, fontSize:12)), SizedBox(height:10), Text("Brand: $selectedBrand\nBarcode: ${barcodeCtrl.text}\n📍 $useLat,$useLng\n📋 $saps", style: TextStyle(fontSize:11)), SizedBox(height:15), Text("WhatsApp to SAPS Task Team:", style: TextStyle(fontSize:10, fontWeight: FontWeight.bold)), SizedBox(height:5), InkWell(onTap: (){ html.window.open(waUrl, "_blank"); }, child: Container(padding: EdgeInsets.all(10), color: Colors.green, child: Row(children: [Icon(Icons.message, color: Colors.white), SizedBox(width:5), Text("SEND WHATSAPP TO SAPS", style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize:11))])))]), actions: [TextButton(onPressed: ()=> Navigator.pop(context), child: Text("CLOSE"))]));
  }
  @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: Text("CITIZEN SCAN - NO LOGIN"), backgroundColor: Colors.green, foregroundColor: Colors.white), body: SingleChildScrollView(padding: EdgeInsets.all(16), child: Column(children: [Container(width: double.infinity, padding: EdgeInsets.all(12), color: Colors.green[50], child: Column(children: [Icon(Icons.my_location, color: Colors.green), Text("Your Location (Auto)", style: TextStyle(fontWeight: FontWeight.bold, fontSize:12)), Text(gps, style: TextStyle(fontSize:11), textAlign: TextAlign.center)])), SizedBox(height:15), DropdownButtonFormField<String>(value: selectedBrand, isExpanded:true, decoration: InputDecoration(labelText: "Select Product", border: OutlineInputBorder()), items: brands.map((b)=> DropdownMenuItem(value:b, child: Text(b, style: TextStyle(fontSize:12)))).toList(), onChanged: (v)=> setState(()=> selectedBrand=v!)), SizedBox(height:10), TextField(controller: barcodeCtrl, decoration: InputDecoration(labelText: "Scan or Type Barcode", prefixIcon: Icon(Icons.qr_code), border: OutlineInputBorder())), SizedBox(height:15), SizedBox(width: double.infinity, height:55, child: ElevatedButton.icon(icon: Icon(Icons.warning), label: Text("REPORT SUSPECT PRODUCT"), style: ElevatedButton.styleFrom(backgroundColor: Colors.red, foregroundColor: Colors.white, textStyle: TextStyle(fontWeight: FontWeight.bold)), onPressed: submit)), SizedBox(height:10), Text("Auto: Location + SAPS No + WhatsApp + CIPC logged\nNo login needed - For all citizens in SA", style: TextStyle(fontSize:10, color: Colors.grey), textAlign: TextAlign.center)]))); }
}

// ===== ADMIN DASHBOARD STAGE 3 WITH WHATSAPP =====
class DashboardPage extends StatefulWidget { @override _DashboardPageState createState() => _DashboardPageState(); }
class _DashboardPageState extends State<DashboardPage> {
  double? lat,lng; double? acc; String gpsStatus="Tap GPS button"; List<Map<String,dynamic>> incidents=[];
  String selectedBrand="Coca-Cola 2L"; final barcodeCtrl=TextEditingController(text: "6001234567890");
  final List<String> brands50=["Coca-Cola 2L","Coca-Cola 500ml","Fanta Orange","Sprite","Stoney","Lays Salt & Vinegar","Lays Tomato","Simba Chips","Doritos","Nik Naks","Sunlight Dish 750ml","Sunlight Bar","Stay Soft","Domestos","Ariel Washing","OMO Washing","Colgate Toothpaste","Always Pads","Pampers","Nivea Lotion","Vaseline Blue Seal","Lux Soap","Dove Soap","Shield Roll-on","Head & Shoulders","Castle Lager","Black Label","Savanna Cider","Hunters Gold","Heineken","White Star Maize","Iwisa Maize","Tastic Rice","Koo Baked Beans","Lucky Star Pilchards","All Gold Tomato","Crosse & Blackwell Mayo","Robertsons Spice","Knorr Soup","Maggi Noodles","Weet-Bix","Corn Flakes Kelloggs","Jungle Oats","Oros","Energade","Amarula","Glenfiddich (FAKE ALERT)","Johnnie Walker Black","Hennessy Cognac","Pringle Original"];
