  void _getRealGPS(){ setState(()=> gpsStatus="🔍 Getting REAL phone GPS... Allow permission!"); try{ html.window.navigator.geolocation.getCurrentPosition().then((pos){ setState(){ lat=pos.coords!.latitude!.toDouble(); lng=pos.coords!.longitude!.toDouble(); acc=pos.coords!.accuracy!.toDouble(); gpsStatus="${lat!.toStringAsFixed(6)}, ${lng!.toStringAsFixed(6)} - ${acc!.toStringAsFixed(1)}m - REAL PHONE GPS!"; }; }).catchError((e){ setState(()=> gpsStatus="Allow location! Fallback Bethelsdorp"); lat=-33.8529; lng=25.5800; }); }catch(e){ setState(){ gpsStatus="Fallback"; lat=-33.8529; lng=25.5800; } } }
  void onScan(){ double useLat=lat??-33.8529; double useLng=lng??25.5800; var inc={"time":DateTime.now(),"barcode":barcodeCtrl.text,"brand":selectedBrand,"status":"SUSPECT - VERIFICATION REQUIRED","lat":useLat,"lng":useLng,"sapsNo":"SAPS-${DateTime.now().millisecondsSinceEpoch}","mapsUrl":"https://www.google.com/maps/search/?api=1&query=$useLat,$useLng"}; setState(()=> incidents.insert(0, inc)); ScaffoldMessenger.of(context).showSnackBar(SnackBar(backgroundColor: Colors.red, content: Text("🚨 SUSPECT: $selectedBrand - ${inc['sapsNo']}"))); }
  void whatsAppSAPS(Map<String,dynamic> d){ String msg="🚨 *SAPS TASK TEAM ALERT - ScanSafeAfrica*\n\nBrand: ${d['brand']}\nBarcode: ${d['barcode']}\nStatus: ${d['status']}\n📍 ${d['lat']},${d['lng']}\n🗺️ ${d['mapsUrl']}\n📋 ${d['sapsNo']}\n⏰ ${d['time']}\n\nAction Required: Verify & Raid if needed"; String url="https://wa.me/27700000000?text=${Uri.encodeComponent(msg)}"; html.window.open(url, "_blank"); }
  void exportSAPS(){ if(incidents.isEmpty){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text("No incidents"))); return; } String csv="SAPS No,Time,Brand,Barcode,Lat,Lng,Maps,Status\n"; for(var d in incidents){ csv+="${d['sapsNo']},${d['time']},${d['brand']},${d['barcode']},${d['lat']},${d['lng']},${d['mapsUrl']},${d['status']}\n"; } showDialog(context: context, builder: (_)=> AlertDialog(title: Text("SAPS EXPORT - ${incidents.length} CASES"), content: SingleChildScrollView(child: Container(padding: EdgeInsets.all(8), color: Colors.grey[200], child: SelectableText(csv, style: TextStyle(fontSize:8, fontFamily:'monospace')))), actions: [TextButton(onPressed: ()=> Navigator.pop(context), child: Text("CLOSE"))])); }
  @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: Text("STAGE 3 ADMIN - ${incidents.length} SUSPECT"), backgroundColor: Color(0xFF0D2C54), foregroundColor: Colors.white, actions: [IconButton(icon: Icon(Icons.download), onPressed: exportSAPS), IconButton(icon: Icon(Icons.my_location), onPressed: _getRealGPS)]), body: Column(children: [Container(width: double.infinity, color: lat==null? Colors.orange[50]: Colors.green[50], padding: EdgeInsets.all(10), child: Column(children: [Row(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(Icons.gps_fixed, color: lat==null? Colors.orange: Colors.green, size:18), SizedBox(width:5), Text(lat==null?"REAL GPS - TAP":"✅ REAL GPS ACTIVE", style: TextStyle(fontWeight: FontWeight.bold, fontSize:12))]), Text(gpsStatus, style: TextStyle(fontSize:11), textAlign: TextAlign.center)])), Container(padding: EdgeInsets.all(10), child: Column(children: [Row(children: [Expanded(flex:3, child: DropdownButtonFormField<String>(value: selectedBrand, isExpanded:true, decoration: InputDecoration(labelText: "50 BRANDS", border: OutlineInputBorder(), contentPadding: EdgeInsets.symmetric(horizontal:10, vertical:5)), items: brands50.map((b)=> DropdownMenuItem(value:b, child: Text(b, style: TextStyle(fontSize:11)))).toList(), onChanged: (v)=> setState(()=> selectedBrand=v!))), SizedBox(width:8), Expanded(flex:2, child: TextField(controller: barcodeCtrl, decoration: InputDecoration(labelText: "Barcode", border: OutlineInputBorder(), contentPadding: EdgeInsets.symmetric(horizontal:10, vertical:5)), style: TextStyle(fontSize:12))) ]), SizedBox(height:8), SizedBox(width: double.infinity, height:45, child: ElevatedButton.icon(icon: Icon(Icons.qr_code_scanner), label: Text("SCAN SUSPECT & REPORT"), style: ElevatedButton.styleFrom(backgroundColor: Colors.red, foregroundColor: Colors.white), onPressed: onScan))])), if(incidents.isNotEmpty) Container(padding: EdgeInsets.symmetric(horizontal:10, vertical:5), color: Colors.blue[50], child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text("Total: ${incidents.length}", style: TextStyle(fontSize:11, fontWeight: FontWeight.bold)), TextButton(onPressed: exportSAPS, child: Text("EXPORT SAPS", style: TextStyle(fontSize:11, fontWeight: FontWeight.bold))) ])), Expanded(child: incidents.isEmpty? Center(child: Text("No SUSPECT yet")) : ListView.builder(itemCount: incidents.length, itemBuilder: (_,i){ var d=incidents[i]; return Card(color: Colors.orange[50], margin: EdgeInsets.symmetric(horizontal:8, vertical:4), child: ListTile(leading: Icon(Icons.warning, color: Colors.red), title: Text(d['brand'], style: TextStyle(fontWeight: FontWeight.bold, fontSize:13)), subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text("Barcode: ${d['barcode']} | ${d['sapsNo']}", style: TextStyle(fontSize:10)), Text("📍 ${d['lat'].toStringAsFixed(6)}, ${d['lng'].toStringAsFixed(6)}", style: TextStyle(fontSize:10)), Text("${d['status']}", style: TextStyle(fontSize:9, color: Colors.red, fontWeight: FontWeight.bold))]), trailing: IconButton(icon: Icon(Icons.message, color: Colors.green), tooltip: "WhatsApp SAPS", onPressed: ()=> whatsAppSAPS(d)))); })),]))); }
}
